/* Company branding: name and logo (made by scripts/build_brand.py from assets/logo.png). */
window.GL_BRAND = {
  name: 'HINDUSTHAN FINCAP CONSULTANCY LLP',
  short: 'Hindusthan FinCap',
  w: 298, h: 147,
  logo: 'data:image/png;base64,',
  mark: 'data:image/png;base64,',
  jpgHex: ''
};
(function () {
  document.querySelectorAll('[data-brand-logo]').forEach((img) => { img.src = window.GL_BRAND.logo; });
  document.querySelectorAll('[data-brand-name]').forEach((el) => { el.textContent = window.GL_BRAND.name; });
  const fav = document.querySelector('link[rel=icon]'); if (fav) fav.href = window.GL_BRAND.mark;
})();
